<?php
require_once __DIR__.'/scheduled-notifications.php';
if(!scheduleReady($db)){echo '<section class="card"><h2>定时通知</h2><p class="notice">服务数据库尚未升级；当前不会自动发送。部署完成后才能启用。</p></section>';return;}
$pageNumber=max(1,min(100000,(int)($_GET['page']??1)));$offset=($pageNumber-1)*20;
$planRows=query('SELECT p.*,s.state,s.revision,s.audience_json,(SELECT COUNT(*) FROM notification_schedule_runs r WHERE r.plan_id=p.id) run_count FROM notification_plans p LEFT JOIN notification_plan_settings s ON s.plan_id=p.id ORDER BY p.id DESC LIMIT 21 OFFSET '.$offset)->fetchAll();$more=count($planRows)>20;$planRows=array_slice($planRows,0,20);
$selectedId=max(0,(int)($_GET['plan']??0));$selected=$selectedId?query('SELECT p.*,s.state,s.revision,s.audience_json FROM notification_plans p LEFT JOIN notification_plan_settings s ON s.plan_id=p.id WHERE p.id=?',[$selectedId])->fetch():null;
$templates=query('SELECT id,name,enabled FROM notification_templates WHERE active=1 ORDER BY name,id')->fetchAll();
$labels=['draft'=>'草稿','enabled'=>'自动发送中','paused'=>'已暂停'];$weekNames=[1=>'周一',2=>'周二',3=>'周三',4=>'周四',5=>'周五',6=>'周六',7=>'周日'];
?>
<section class="card"><div class="section-head"><div><h2>定时通知</h2><p class="muted">先保存草稿，核对接收范围和人数，再启用。仅向已开启通知的成员发送。</p></div><a class="secondary" href="?p=notifications&amp;tab=plans&amp;new=1">新建计划</a></div><div class="table-wrap"><table><thead><tr><th>计划</th><th>发送时间</th><th>接收范围</th><th>状态</th><th></th></tr></thead><tbody><?php foreach($planRows as $plan):$audience=json_decode($plan['audience_json']??'{}',true);?><tr><td><?=h($plan['name'])?></td><td><?=h(implode('、',array_map(fn($n)=>$weekNames[(int)$n]??'待设置',explode(',',$plan['weekdays']))))?> <?=sprintf('%02d:%02d',(int)$plan['hour'],(int)$plan['minute'])?><small><?=h($plan['timezone'])?></small></td><td><?=h(['all'=>'所有正常成员','members'=>'会员','selected'=>'指定成员'][$audience['mode']??'selected'])?></td><td><?=h($labels[$plan['state']??'draft'])?></td><td><a href="?p=notifications&amp;tab=plans&amp;plan=<?=(int)$plan['id']?>">查看与设置</a></td></tr><?php endforeach;if(!$planRows):?><tr><td colspan="5" class="empty">还没有通知计划</td></tr><?php endif?></tbody></table></div><?php adminPageCount($pageNumber,$more);?></section>
<?php if($selected||isset($_GET['new'])):$edit=$selected?:[];$audience=json_decode($edit['audience_json']??'{}',true)?:['mode'=>'selected','user_ids'=>[]];?>
<section class="card narrow"><div class="section-head"><h2><?=$selected?'设置计划':'新建计划'?></h2><a href="?p=notifications&amp;tab=plans">收起</a></div>
<form method="post" data-inline-editor><?php csrfField()?><input type="hidden" name="action" value="<?=$selected?'notification_plan_update':'notification_plan_create'?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><input type="hidden" name="expected_revision" value="<?=(int)($edit['revision']??0)?>"><label>计划名称<input name="name" required maxlength="80" value="<?=h($edit['name']??'')?>" placeholder="例如：周末训练提醒"></label><label>发送哪条文案<select name="template_id" required><option value="">请选择</option><?php foreach($templates as $template):?><option value="<?=(int)$template['id']?>" <?=($edit['template_id']??0)==$template['id']?'selected':''?>><?=h($template['name'])?><?=!$template['enabled']?'（文案已停用）':''?></option><?php endforeach?></select></label><fieldset><legend>每周哪几天发送</legend><div class="tag-picker"><?php foreach($weekNames as $day=>$name):?><label class="switch"><input type="checkbox" name="weekdays[]" value="<?=$day?>" <?=in_array((string)$day,explode(',',$edit['weekdays']??'1,3,5'),true)?'checked':''?>><?=$name?></label><?php endforeach?></div></fieldset><div class="profile-grid"><label>几点发送<input type="time" name="send_time" required value="<?=sprintf('%02d:%02d',(int)($edit['hour']??19),(int)($edit['minute']??30))?>"></label><label>按哪个地区时间<select name="timezone"><?php $zones=['Asia/Shanghai'=>'北京时间','Asia/Tokyo'=>'日本时间','Asia/Seoul'=>'韩国时间','Asia/Singapore'=>'新加坡时间','UTC'=>'UTC'];if(isset($edit['timezone'])&&!isset($zones[$edit['timezone']]))$zones[$edit['timezone']]=$edit['timezone'];foreach($zones as $key=>$value):?><option value="<?=$key?>" <?=($edit['timezone']??'Asia/Shanghai')===$key?'selected':''?>><?=h($value)?></option><?php endforeach?></select></label></div><label>发给谁<select name="audience_mode"><?php foreach(['selected'=>'指定成员','members'=>'权益有效的会员','all'=>'所有正常成员'] as $key=>$label):?><option value="<?=$key?>" <?=($audience['mode']??'selected')===$key?'selected':''?>><?=h($label)?></option><?php endforeach?></select></label><label>指定成员编号<textarea name="user_refs" rows="3" placeholder="仅选择“指定成员”时填写，每行一个，例如 NO. 010001"><?=h(implode("\n",array_map('clubNumber',$audience['user_ids']??[])))?></textarea></label><button>保存草稿</button><small>修改已启用计划会先暂停，需要重新核对并启用。</small></form></section>
<?php if($selected):$category=query('SELECT category FROM notification_templates WHERE id=?',[$selected['template_id']])->fetchColumn()?:$selected['category'];$count=scheduleRecipientCount($db,scheduleAudience($audience),$category);?>
<section class="card narrow"><h2>接收范围核对</h2><p>当前符合范围、已开启通知且登录有效的成员：<strong><?=$count?> 位</strong>。</p><p class="muted">实际发送时重新检查用户设置；免打扰期间会延后。每个计划每天最多发送一轮。</p>
<?php if(adminCanWriteAction('notification_plan_publish')):if(($selected['state']??'draft')==='enabled'):?><form method="post" data-inline-editor data-confirm="暂停这个计划的后续发送？"><?php csrfField()?><input type="hidden" name="action" value="notification_plan_pause"><input type="hidden" name="id" value="<?=$selectedId?>"><input type="hidden" name="expected_revision" value="<?=(int)$selected['revision']?>"><button class="secondary">暂停自动发送</button></form><?php else:?><form method="post" data-inline-editor data-confirm="启用后，将按所选时间与接收范围自动发送通知。确认继续？"><?php csrfField()?><input type="hidden" name="action" value="notification_plan_publish"><input type="hidden" name="id" value="<?=$selectedId?>"><input type="hidden" name="expected_revision" value="<?=(int)($selected['revision']??0)?>"><label>输入上面核对的人数<input name="confirmed_count" type="number" min="1" required></label><label>当前管理员密码<input name="current_password" type="password" autocomplete="current-password" required></label><button>启用自动发送</button></form><?php endif;endif?>
</section>
<section class="card"><h2>最近发送结果</h2><div class="table-wrap"><table><thead><tr><th>成员</th><th>计划日期</th><th>结果</th><th>原因</th></tr></thead><tbody><?php $deliveries=query('SELECT d.user_id,d.status,d.reason,r.occurrence_date FROM notification_schedule_deliveries d JOIN notification_schedule_runs r ON r.id=d.run_id WHERE r.plan_id=? ORDER BY d.id DESC LIMIT 20',[$selectedId])->fetchAll();foreach($deliveries as $delivery):?><tr><td><?=h(clubNumber((int)$delivery['user_id']))?></td><td><?=h($delivery['occurrence_date'])?></td><td><?=h(['pending'=>'等待发送','sending'=>'正在发送','sent'=>'苹果已接收','skipped'=>'未发送','failed'=>'发送失败','uncertain'=>'结果待核对'][$delivery['status']])?></td><td><?=h(['SendOutcomeUnknown'=>'无法确认是否已发出，未自动重发','QuietHours'=>'用户免打扰时段','PlanChangedOrPaused'=>'计划已修改或暂停','NotificationExpired'=>'已过有效时间','DeviceOrPermissionUnavailable'=>'用户已退出、关闭通知或被停发','DailyLimitReached'=>'今日主动提醒已达上限','AlreadySent'=>'相同提醒已处理','AcceptedByApple'=>'苹果推送服务已接收','Retrying'=>'稍后自动重试'][$delivery['reason']]??($delivery['reason']?:'—'))?></td></tr><?php endforeach;if(!$deliveries):?><tr><td colspan="4" class="empty">尚未到发送时间，或还没有符合范围的成员。</td></tr><?php endif?></tbody></table></div></section>
<?php endif;endif?>
